// Tarjan SCC over Invar's import graph, value-imports vs all-imports.
import { readFileSync, readdirSync, statSync, existsSync } from 'node:fs';
import { join, dirname, resolve } from 'node:path';

const ROOT = '~/dev/invar/src';
const files = [];
(function walk(dir) {
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    const info = statSync(full);
    if (info.isDirectory()) walk(full);
    else if (/\.ts$/.test(entry) && !/\.(test|spec)\.ts$/.test(entry) && !full.includes('__tests__')) files.push(full);
  }
})(ROOT);

const fileSet = new Set(files);
function resolveImport(fromFile, spec) {
  if (!spec.startsWith('.')) return null; // external
  const base = resolve(dirname(fromFile), spec);
  for (const candidate of [base + '.ts', join(base, 'index.ts'), base]) {
    if (fileSet.has(candidate)) return candidate;
  }
  return null;
}

// valueEdges: imports that survive type erasure (not `import type`)
const valueEdges = new Map();
const allEdges = new Map();
const importRe = /^\s*import\s+(type\s+)?[^'"]*from\s+['"]([^'"]+)['"]/gm;
const sideEffectRe = /^\s*import\s+['"]([^'"]+)['"]/gm;
const exportFromRe = /^\s*export\s+(type\s+)?[^'"]*from\s+['"]([^'"]+)['"]/gm;

for (const file of files) {
  const source = readFileSync(file, 'utf8');
  const value = new Set(), all = new Set();
  for (const match of source.matchAll(importRe)) {
    const target = resolveImport(file, match[2]);
    if (!target) continue;
    all.add(target);
    if (!match[1]) value.add(target);
  }
  for (const match of source.matchAll(sideEffectRe)) {
    const target = resolveImport(file, match[1]);
    if (target) { all.add(target); value.add(target); }
  }
  for (const match of source.matchAll(exportFromRe)) {
    const target = resolveImport(file, match[2]);
    if (!target) continue;
    all.add(target);
    if (!match[1]) value.add(target);
  }
  valueEdges.set(file, value);
  allEdges.set(file, all);
}

function tarjan(edges) {
  let index = 0;
  const stack = [], onStack = new Set(), indices = new Map(), lowlinks = new Map(), sccs = [];
  function strongconnect(node) {
    indices.set(node, index); lowlinks.set(node, index); index++;
    stack.push(node); onStack.add(node);
    for (const next of edges.get(node) ?? []) {
      if (!indices.has(next)) { strongconnect(next); lowlinks.set(node, Math.min(lowlinks.get(node), lowlinks.get(next))); }
      else if (onStack.has(next)) lowlinks.set(node, Math.min(lowlinks.get(node), indices.get(next)));
    }
    if (lowlinks.get(node) === indices.get(node)) {
      const scc = [];
      let member;
      do { member = stack.pop(); onStack.delete(member); scc.push(member); } while (member !== node);
      if (scc.length > 1) sccs.push(scc);
    }
  }
  for (const node of edges.keys()) if (!indices.has(node)) strongconnect(node);
  return sccs;
}

const valueSccs = tarjan(valueEdges);
const allSccs = tarjan(allEdges);
console.log('files analyzed:', files.length);
console.log('value-import cycles (SCCs >1):', valueSccs.length);
for (const scc of valueSccs) console.log('  VALUE CYCLE:', scc.map(f => f.replace(ROOT + '/', '')).join(' <-> '));
console.log('all-import (incl. type-only) cycles:', allSccs.length);
for (const scc of allSccs) console.log('  scc size', scc.length, ':', scc.slice(0, 3).map(f => f.replace(ROOT + '/', '')).join(', '), scc.length > 3 ? '…' : '');

