1	// Disposable working-directory watcher. A storm of filesystem events owns only one resettable
2	// timer and therefore produces one Git refresh after the tree settles.
3	//
4	// It watches the working tree by WALKING it and establishing one NON-recursive watch per
5	// directory, SKIPPING every directory git considers ignored (queried with `git check-ignore`)
6	// plus `.git`. A single recursive watch on the root would descend into ignored trees like
7	// `node_modules` — thousands of nested directories, each an open filesystem watch handle, a real
8	// handle/memory sink on large projects — and on this platform Bun's recursive watch does not even
9	// reliably deliver nested events. The per-directory walk instead never opens a watch handle inside
10	// an ignored directory: an ignored path is pruned before its watch is ever created.
11	//
12	// invariant: Filesystem notifications arrive in bursts (src/modules/git/git.invariants.md)
13	// invariant: The watcher has one disposable debounce (src/modules/git/git.invariants.md)
14	// invariant: The git panel converges without watcher notifications (src/modules/git/git.invariants.md)
15	// invariant: The watcher never watches inside an ignored directory (src/modules/git/git.invariants.md)
16	import { Static } from 'ivue/extras';
17	import { watch, readdirSync, lstatSync, type FSWatcher } from 'node:fs';
