24	    return new Set(['node_modules', '.git', 'dist']);
25	  }
26	  constructor(
27	    readonly cwd: string,
28	    protected readonly repository: GitRepository.Model,
29	    options: GitWatcherOptions = {},
30	  ) {
31	    this.onReconciled = options.onReconciled ?? null;
32	    this.onWatchSetEstablished = options.onWatchSetEstablished ?? null;
33	    this.debounceMilliseconds = Math.max(0, options.debounceMs ?? 80);
34	    this.reconcileIntervalMilliseconds = Math.max(
35	      1,
36	      options.reconcileIntervalMilliseconds ?? 5_000,
37	    );
38	    this.watchSetEstablishmentPromise = this.establishWatchSet(
39	      options.viewPainted,
40	    );
41	  }
42	
43	  protected readonly directoryWatchers = new Map<string, FSWatcher>();
44	  // A SINGLE watch on this worktree's git dir, dedicated to HEAD changes (branch switches).
45	  protected headWatcher: FSWatcher | null = null;
46	  protected debounceTimer: ReturnType<typeof setTimeout> | null = null;
47	  protected reconcileTimer: ReturnType<typeof setInterval> | null = null;
