  background-clip: text;
  color: transparent;
  filter: var(--ivue-link-shadow);
  /* !important: VitePress's scoped rules ([data-v-*]) out-rank this
     selector and would replace the transition, killing the 0.3s stop
     morph; their background/opacity transitions are folded in */
  transition:
    --link-stop-1 0.3s ease,
    --link-stop-2 0.3s ease,
    --link-stop-3 0.3s ease,
    text-decoration-color 0.3s ease,
    background-color 0.25s ease,
    opacity 0.25s ease,
    transform 0.18s ease !important;
}

/* ALWAYS-ON: rest = the gradient */
.vp-doc :is(p, li, td) > a:not([class]):not(:has(code)),
