#!/usr/bin/env python3
# Emits banner HTML for the 14 pre-template posts, house style: grid bg,
# optional mono eyebrow, glowing title, two-line sub, four stat chips.
from pathlib import Path

BASE = """<!doctype html>
<html>
<head>
<meta charset="utf-8" />
<style>
  @font-face {{
    font-family: 'Geist';
    font-style: normal;
    font-weight: 300 800;
    src: url(./fonts/geist-latin.woff2) format('woff2');
  }}
  @font-face {{
    font-family: 'Geist Mono';
    font-style: normal;
    font-weight: 400 600;
    src: url(./fonts/geist-mono-latin.woff2) format('woff2');
  }}
  * {{ margin: 0; padding: 0; box-sizing: border-box; }}
  html, body {{ width: 1200px; height: 630px; overflow: hidden; }}
  body {{
    background:
      radial-gradient(1000px 560px at 50% -20%, rgba(99, 102, 241, 0.25), transparent 60%),
      radial-gradient(900px 560px at 50% 130%, rgba(34, 211, 238, 0.14), transparent 55%),
      #050a18;
    font-family: 'Geist', 'DejaVu Sans', 'Inter', sans-serif;
    position: relative;
  }}
  .grid {{
    position: absolute; inset: 0;
    background-image:
      linear-gradient(rgba(59, 130, 246, 0.06) 1px, transparent 1px),
      linear-gradient(90deg, rgba(59, 130, 246, 0.06) 1px, transparent 1px);
    background-size: 48px 48px;
    mask-image: radial-gradient(760px 480px at 50% 50%, black 25%, transparent 75%);
    -webkit-mask-image: radial-gradient(760px 480px at 50% 50%, black 25%, transparent 75%);
  }}
  .stage {{
    position: absolute; inset: 0;
    display: flex; flex-direction: column;
    align-items: center; justify-content: center;
    gap: 26px; padding: 0 70px 44px;
    text-align: center;
  }}
  .eyebrow {{
    font-family: 'Geist Mono', 'DejaVu Sans Mono', monospace;
    font-size: 19px; letter-spacing: 0.34em; color: #4fd1c5;
    text-shadow: 0 0 16px rgba(45, 212, 191, 0.5);
  }}
  .title {{
    font-size: {title_size}px; font-weight: 750; color: #eaf2ff;
    text-shadow: 0 0 44px rgba(59, 130, 246, 0.5); letter-spacing: -0.015em;
    line-height: 1.12;
  }}
  .title .glow {{ color: #67e8f9; text-shadow: 0 0 36px rgba(34, 211, 238, 0.8); }}
  .sub {{
    font-size: 25px; color: #7e9cd0; line-height: 1.55; max-width: 1000px;
  }}
  .stats {{
    display: flex; justify-content: center; gap: 18px; margin-top: 8px;
  }}
  .stat {{
    display: flex; flex-direction: column; align-items: center; gap: 5px;
    padding: 13px 22px; border-radius: 11px;
    border: 1px solid rgba(96, 165, 250, 0.4);
  }}
  .stat .n {{
    font-family: 'Geist Mono', 'DejaVu Sans Mono', monospace;
    font-size: 24px; color: #67e8f9; text-shadow: 0 0 20px rgba(34, 211, 238, 0.5);
  }}
  .stat .l {{ font-size: 16px; color: #7e9cd0; }}
  .brand {{
    position: absolute; bottom: 34px; width: 1200px; text-align: center;
    font-family: 'Geist Mono', 'DejaVu Sans Mono', monospace;
    font-size: 22px; letter-spacing: 0.08em; color: #7da4e8;
  }}
  .brand b {{ color: #e0ecff; }}
</style>
</head>
<body>
  <div class="grid"></div>
  <div class="stage">
{eyebrow}    <div class="title">{title}</div>
    <div class="sub">{sub}</div>
    <div class="stats">
{stats}    </div>
  </div>
  <div class="brand">∞ <b>ivue</b> blog</div>
</body>
</html>
"""

BANNERS = {
  'introducing-ivue': dict(
    eyebrow='INTRODUCING IVUE', title_size=74,
    title='Plain classes. <span class="glow">One kilobyte.</span>',
    sub='class-based architecture for Vue 3 — full reactivity on plain<br/>classes, and the derivation primitive done right',
    stats=[('1.1 kB','gzipped'),('0','dependencies'),('100%','test coverage'),('22 ms','1M instances')],
  ),
  'one-kilobyte-feature': dict(
    title_size=74,
    title='One kilobyte <span class="glow">is a feature</span>',
    sub='1.1 kB is not a compression achievement — it is what remains when a<br/>design stops needing machinery. small enough to read, small enough to trust',
    stats=[('1,112 B','the whole engine'),('1','prototype transform'),('0','dependencies'),('100%','coverage')],
  ),
  'compu

… [1,358 characters removed from the sample] …

 decade of composables is not the rival — it is the substrate.<br/>classes give the body a spine; composables keep doing what they do best',
    stats=[('composables','the organs'),('classes','the spine'),('$-getters','the joints'),('0','rewrites required')],
  ),
  'inheritance-exile': dict(
    title_size=64,
    title="Inheritance didn't deserve <span class=\"glow\">the exile</span>",
    sub='composition-over-inheritance corrected an abuse, then outlawed a tool —<br/>reactive super chains show what the ban cost',
    stats=[('extends','just works'),('super','stays reactive'),('overrides','cache correctly'),('0','workarounds')],
  ),
  'hot-reload-for-logic': dict(
    title_size=68,
    title='Development should run <span class="glow">production</span>',
    sub='a dev-only proxy preserves state but creates a second execution model —<br/>let Vue own reconstruction so dev exercises the production engine',
    stats=[('1','execution model'),('0','dev-only proxies'),('state','preserved on edit'),('prod','semantics always')],
  ),
  'scrollbar-is-code': dict(
    title_size=74,
    title='The scrollbar <span class="glow">is code</span>',
    sub='a 1,000,000-row list where scrolling itself is virtual — Lenis drives<br/>position over translateY, and nothing costs O(total)',
    stats=[('1M','rows'),('~12','DOM nodes'),('O(viewport)','all costs'),('60 fps','sustained')],
  ),
  'this-method-era': dict(
    title_size=64,
    title='this.method, <span class="glow">finally safe to pass</span>',
    sub='a decade of () =&gt; this.method() wrappers, .bind(this) rituals, and shipped<br/>undefined-this bugs — ended by lazy binding on the prototype',
    stats=[('bound','lazily, once'),('stable','function identity'),('0','arrow wrappers'),('prototype','owns the logic')],
  ),
  'twenty-million-cells': dict(
    title_size=66,
    title='The 20,000,000-cell <span class="glow">document</span>',
    sub='a spreadsheet Google Sheets cannot represent, fully reactive —<br/>and you can create it in your browser right now',
    stats=[('20M','cells'),('4.7 B','per cell'),('fully','reactive'),('live','in your browser')],
  ),
  'vscode-hand-rolled-decade': dict(
    title_size=58,
    title='VS Code spent a decade hand-rolling <span class="glow">reactive classes</span>',
    sub='the most influential TypeScript app is class-OOP with no framework — emitters,<br/>disposables, DI, its own signals. every subsystem maps to one ivue feature',
    stats=[('emitters','→ ref getters'),('disposables','→ $stopEffects'),('DI','→ $-getters'),('signals','→ plain getters')],
  ),
  'the-object-should-tell-the-truth': dict(
    title_size=64,
    title='The object should <span class="glow">tell the truth</span>',
    sub='state is explicit, caching is intentional, everything else stays pure —<br/>the runtime semantics of an object, visible in its source',
    stats=[('state','= ref getter'),('cache','= computed()'),('pure','= plain getter'),('semantics','in the source')],
  ),
  'win-by-reduction': dict(
    title_size=60,
    title='Win by reduction. <span class="glow">Win by construction.</span>',
    sub='the strongest architecture does not manage complexity better — it removes<br/>the conditions that create it, then makes the remaining guarantees structural',
    stats=[('remove','the conditions'),('construct','the guarantees'),('structural','not vigilant'),('0','failure classes left')],
  ),
}

out = Path('~/dev/ivue/.claude/skills/blog-banner/banners')
for slug, spec in BANNERS.items():
  eyebrow = f'    <div class="eyebrow">{spec["eyebrow"]}</div>\n' if 'eyebrow' in spec else ''
  stats = ''.join(
    f'      <div class="stat"><span class="n">{n}</span><span class="l">{l}</span></div>\n'
    for n, l in spec['stats']
  )
  html = BASE.format(
    title_size=spec['title_size'], title=spec['title'], sub=spec['sub'],
    eyebrow=eyebrow, stats=stats,
  )
  (out / f'{slug}.html').write_text(html)
  print('wrote', slug)
print(len(BANNERS), 'banner sources')

